use std::os::unix::process::CommandExt;
use std::process::Command;
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode = &args[1];
    let bin = "/workspace/dataset/test4_executable";
    match mode.as_str() {
        // exec with a single argument of N bytes
        "long" => {
            let n: usize = args[2].parse().unwrap();
            let s = "a".repeat(n);
            let e = Command::new(bin).arg(&s).exec();
            eprintln!("HARNESS: execve failed: {:?} raw_os_error={:?}", e.kind(), e.raw_os_error());
        }
        // exec with argc == 0 (no argv[0] at all)
        "argc0" => {
            let e = Command::new(bin).args::<[&str;0],&str>([]).arg0("").exec();
            eprintln!("HARNESS: execve failed: {:?}", e);
        }
        _ => {}
    }
}
EOF
